TLM.f("Sancti/01-24",{"officium":"S. Timothei Episcopi et Martyris","rule":["vide C2;","Gloria"],"fallback":"Commune/C2c","from":{"Introitus":"Commune/C2c","Tractus":"Commune/C2c","Evangelium":"Commune/C2c","Offertorium":"Commune/C2c","Communio":"Commune/C2c"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 45:30"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Infirmitátem nostram réspice, omnípotens Deus: et, quia pondus própriæ actiónis gravat, beáti Timothei Mártyris tui atque Pontíficis intercéssio gloriósa nos prótegat."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"1 Tim 6:11-16"},{"k":"text","la":"Caríssime: Sectáre justítiam, pietátem, fidem, caritátem, patiéntiam, mansuetúdinem. Certa bonum certámen fídei, apprehénde vitam ætérnam, in qua vocátus es, et conféssus bonam confessionem coram multis téstibus. Præcípio tibi coram Deo, qui vivíficat ómnia, et Christo Jesu, qui testimónium réddidit sub Póntio Piláto, bonam confessiónem: ut serves mandátum sine mácula, irreprehensíbile usque in advéntum Dómini nostri Jesu Christi, quem suis tempóribus osténdet beátus et solus potens, Rex regum et Dóminus dominántium: qui solus habet immortalitátem, et lucem inhábitat inaccessíbilem: quem nullus hóminum vidit, sed nec vidére potest: cui honor et impérium sempitérnum. Amen."}],"Graduale":[{"k":"ref","la":"Ps 88, 21-23"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et brácchium meum confortábit eum. Nihil profíciet inimícus in eo, et fílius iniquitátis non nocébit ei."},{"k":"sep"},{"k":"ref","la":"Ps 109, 4"},{"k":"text","la":"Allelúia, allelúia."},{"k":"text","la":"Tu es sacérdos in aetérnum, secúndum órdinem Melchísedech. Allelúia."}],"Tractus":[{"k":"ref","la":"Ps 88:21-23"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."},{"k":"text","la":"Nihil profíciet inimícus in eo, et fílius iniquitátis non nocébit ei.","mark":"V"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 14:26-33"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis: Si quis venit ad me, et non odit patrem suum, et matrem, et uxórem, et fílios, et fratres, et soróres, adhuc autem et ánimam suam, non potest meus esse discípulus. Et qui non bájulat crucem suam, et venit post me, non potest meus esse discípulus. Quis enim ex vobis volens turrim ædificáre, non prius sedens cómputat sumptus, qui necessárii sunt, si hábeat ad perficiéndum; ne, posteáquam posúerit fundaméntum, et non potúerit perfícere, omnes, qui vident, incípiant illúdere ei, dicéntes: Quia hic homo cœpit ædificáre, et non pótuit consummáre? Aut quis rex itúrus commíttere bellum advérsus álium regem, non sedens prius cógitat, si possit cum decem mílibus occúrrere ei, qui cum vigínti mílibus venit ad se? Alióquin, adhuc illo longe agénte, legatiónem mittens, rogat ea, quæ pacis sunt. Sic ergo omnis ex vobis, qui non renúntiat ómnibus, quæ póssidet, non potest meus esse discípulus."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, beáti Timothei Mártyris tui atque Pontíficis dicátas méritis, benígnus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 88:36; 88:37-38"},{"k":"text","la":"Semel jurávi in sancto meo: Semen ejus in ætérnum manébit: et sedes ejus sicut sol in conspéctu meo, et sicut luna perfécta in ætérnum, et testis in coelo fidélis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti participatióne múneris sacri, quaésumus, Dómine Deus noster: ut, cuius exséquimur cultum, intercedénte beáto Timótheo Mártyre tuo atque Pontífice, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c02c414c737dacfd":{"t":"Sir 45, 30, Ps 131, 1\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve njegove krotkosti.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 45, 30) Sklopio je Gospodin s njime savez mira učinio ga knezom da zauvijek bude u svećeničkom dostojanstvu.","kn":"(Grkv. 45, 30). Gospodin je sklopio s njime savez mira i učinio ga knezom, da zauvijek bude u svećeničkom dostojanstvu. (Ps. 131, 1). Sjeti se, Gospodine, Davida i sve njegove pobožnosti. Slava Ocu. Gospodin ...","knRef":"Kniewald 1942, str. 478–479 (snimka 240) (OCR)"},"4d37b70c72c6e6f1":{"t":"<i>Pomolimo se</i>.\nObazri se, Gospodine, na našu slabost, pa jer nas pritište težina vlastitog djelovanja, neka nas štiti slavni zagovor blaženog tvojeg mučenika i biskupa Timoteja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Obazri, se, svemogući Bože, na slalbost Tvojih vjernika, koje pritište teret vlastitih čina i podaj, da nas zaštiti slavni zagovor blaženog I., Tvoga mučenika i biskupa. Po G. n.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"a7fccf547fa0a37a":{"t":"1 Tim 6, 11-16\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, traži pravdu, pobožnost, vjeru, ljubav, strpljivost i blagost. Vojuj u borbi za vjeru da postigneš vječni život u koji si pozvan i za koji si lijepo svjedočio pred mnogim svjedocima. Nalažem ti pred Bogom koji svemu daje život i pred Isusom Kristom koji je dobro svjedočio pred Poncijem Pilatom da bez ljage i bez prijekora vršiš ovu zapovijed do dolaska našega Gospodina Isusa Krista koji će se u svoje vrijeme pokazati kao blaženi i jedini mogući Vladar vladara i Gospodar gospodara On jedini je besmrtan i boravi u svjetlosti kojoj se ne može nitko približiti. Njemu kojega nitko nije vidio niti može vidjeti neka bude čast i vječna vlast. Amen.","kn":"Čitanje poslanice bi. Pavla apostola Timoteju (I, 6, 11-16). Predragi! Traži pravdu, /pobožnost, vjeru, ljubav, strpljivost, krotkost. Vojuj za vjeru dobar boj, da postigneš vječni život, na koji si pozvan i za koji si dobro svjedo-čio pred mnogo svjedoka. Zapovijedam ti pred Bogom, koji svemu daje život, i pred Isusom Kristom, koji je dao dobro svjedočanstvo pred Poncijem Pilatom, da bez ljage i bez prijekora držiš zapovijed sve do dolaska Gospodina našega Isusa Krista, koji će u svoje vrijeme pokazati blaženi i jedino mogući Kralj kraljeva i Gospodar gospodara. On je sam besmrtan i stanuje u svjetlosti, kojoj se ne može pristuipiti. Njemu, koga nijedan čovjek nije vidio niti može vidjeti, neka bude čast i vječna vlast. Amen.","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"cbfb4580010d40ee":{"t":"Ps 88, 21-23\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. Neprijatelj biti nemoćan prema njemu, i sin bezakonja neće se usuditi da mu naškodi.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.","kn":"(Ps. 88, 21-23). Izabrao sam Davida za slugu svoga i pomazao sam ga svojim svetim uljem. Moja će ga^ ruka štititi i jačati. I bit će nemoćan naprijatelj protiv njega i sin mu bezakonja ne će nauditi. Aleluja, aleluja (Ps. 109, 4), Za uvijek ti si , svećenik po redu Melkizedekovu. Aleluja. Ii;-' . '","knRef":"Kniewald 1942, str. 788–789 (snimka 395) (OCR)"},"80912993d51d297a":{"t":"Lk 14, 26-33\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus narodu: Ako tko dolazi k meni, a ne ostavi svojega oca i majku, ženu i djecu, braću i sestre, pa i samoga sebe, ne može biti moj učenik. I tko ne nosi svoj križ i ne pođe za mnom, ne može biti moj učenik. Jer kad tko od vas odluči sazidati kulu, zar najprije ne sjedne i ne računa, koliko treba troškova da mogne dovršiti, da mu se svi koji vide kako je postavio temelje a nije dovršio, ne stanu rugati: Ovaj je čovjek počeo zidati, a nije mogao dovršiti? Ili koji vladar kad polazi u rat protiv drugoga vladara, zar ne sjedne prije i ne razmišlja, može li se s deset tisuća oprijeti onome koji dolazi protiv njega s dvadeset tisuća? Inače, dok je onaj još daleko, uputit će poslanike i moliti mir. Tako isto nitko od vas koji se ne odreče svega što ima, ne može biti moj učenik.","kn":"t Slijedi sveto evanđelje po Lnki (14, 26-33). U ono vrijeme reče Isus narodu; Ako tko dolazi k meni, a ne mrzi svojega oca i majke i žene i djece i braće i sestara, pa i samoga sebe, ne može biti moj učenik. I tko ne nosi svojega križa i ne ide za mnom, ne može biti moj učenik. Jer tko od vas hoteći graditi kulu, najprije ne sjedne i računa, koliko treba troška, da mogne dovršiti, da mu se svi, koji vide, da je postavio temelje, a nije dovršio, ne počnu rugati i govoriti: Ovaj je čovjek počeo graditi, a nije mogao dovršiti. Ili koji kralj, kad ide ratovati protiv drugoga kralja, ne sjedne prije i promisli, da li se može oprijeti s deset tisuća onomu, koji dolazi na njega s dvadeset tisuća.' Jer će inače, dok je onaj još daleko, uputiti poslanike i moliti za mir. Isto tako nitko od vas, koji se ne odreče svega, što ima, ne može biti moj učenik.","knRef":"Kniewald 1942, str. 542–543 (snimka 272) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"3655190620f6fb3b":{"t":"Dobrostivo primi, Gospodine, prinose koje ti posvećujemo po zaslugama blaženog tvojeg mučenika i biskupa Timoteja i daj da nam postanu trajna pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, blagostivo žrtve, što Ti ih prinosimo zaslugama blaženoga I., Tvoga mučenika i biskupa i podaj, da nam ishode neprestanu Tvoju pomoć. Po G. n.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"3eefd390cb354c24":{"t":"Ps 88, 36-38\nZakleo sam se svecu svome: Potomstvo će njegovo ostati dovijeka. I prijestolje će njegovo biti kao sunce, kao puni mjesec u vijeke i kao duga koja je vjeran znak na nebesima.","kn":"(Ps. 88, 36-38). Jednom se zakleh svetošću svojom: potomstvo će njegovo ostati u vijeke, i prijesto njegov kao sunce pred licem mojim, i kao mjesec, koji je osnovan u vijeke; i svjedok je na nebu vjeran.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"bc970f4b80ab43dc":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni sudjelovanjem u svetom daru, molimo, Gospodine Bože naš, da po zagovoru tvojeg blaženog mučenika i biskupa Timoteja osjetimo učinak tajne, koju slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Okrijepljeni svetim darovima molimo Te, Gospodine, Bože naš, da zagovorom blaženoga I., Tvoga mučenika i biskupa, osjetimo djelovanje svetih tajna, koje izvršuijemo. Po G. n.","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"cf331c57e9268245":{"t":"Ps 88, 21-23\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja. Neprijatelj biti nemoćan prema njemu, i sin bezakonja neće se usuditi da mu naškodi.\n\nPs 20, 3-4\nTi si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Pretekao si ga slatkim blagoslovom. Postavio si mu na glavu vijenac od dragog kamenja."}}});
